def e_primo(n):
    if n < 2:
        return False
    for d in range(2, n):
        if n % d == 0:
            return False
    return True


def primos_ate(n):
    primos = []
    for numero in range(2, n + 1):
        if e_primo(numero):
            primos.append(numero)
    return primos


print(e_primo(7))
print(primos_ate(10))

