def problemas(senha, minimo=8):
    tem_numero = False
    tem_maiuscula = False
    tem_minuscula = False
    tem_simbolo = False
    for c in senha:
        if c.isdigit():
            tem_numero = True
        if c.isupper():
            tem_maiuscula = True
        if c.islower():
            tem_minuscula = True
        if not c.isalpha() and not c.isdigit():
            tem_simbolo = True

    lista = []
    if len(senha) < minimo:
        lista.append(f"mínimo de {minimo} caracteres")
    if not tem_numero:
        lista.append("falta um número")
    if not tem_maiuscula:
        lista.append("falta uma letra maiúscula")
    if not tem_minuscula:
        lista.append("falta uma letra minúscula")
    if not tem_simbolo:
        lista.append("falta um símbolo")
    return lista


def forca(senha):
    quantos = len(problemas(senha))
    if quantos == 0:
        return "forte"
    elif quantos <= 2:
        return "média"
    else:
        return "fraca"


print(problemas("abc"))
print(forca("Cobra#2024"))

